package br.com.sussmartcare.notification.application; import br.com.sussmartcare.notification.domain.*; import br.com.sussmartcare.notification.infrastructure.*; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class NotificationApplicationService {private final NotificationRepository repo;private final NotificationPreferenceRepository preferences;private final List<NotificationChannel> channels;public NotificationApplicationService(NotificationRepository r,NotificationPreferenceRepository p,List<NotificationChannel> c){repo=r;preferences=p;channels=c;}@Transactional public NotificationPreference preference(UUID patient,boolean smartphone,String preferred,String fallback){return preferences.save(new NotificationPreference(patient,smartphone,preferred,fallback));}
 @Transactional public List<Notification> sendAuto(UUID patient,UUID visit,String type,String message){var p=preferences.findById(patient).orElse(new NotificationPreference(patient,false,"DISPLAY","STAFF_ASSISTED"));var selected=new LinkedHashSet<String>();selected.add(p.isHasSmartphone()?p.getPreferredChannel():"DISPLAY");if(!p.isHasSmartphone())selected.add(p.getFallbackChannel()==null?"STAFF_ASSISTED":p.getFallbackChannel());var result=new ArrayList<Notification>();for(String channel:selected)result.add(send(patient,visit,type,channel,message));return result;}
 @Transactional public Notification send(UUID patient,UUID visit,String type,String channel,String message){var n=repo.save(new Notification(patient,visit,type,channel,message));var adapter=channels.stream().filter(c->c.supports(channel)).findFirst().orElseThrow(()->new IllegalStateException("Canal não suportado: "+channel));adapter.send(n);n.delivered();return repo.save(n);}public List<Notification> history(UUID p){return repo.findByPatientIdOrderByCreatedAtDesc(p);}}
